export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PySet {
  constructor(items) {
    this.items = [];
    this.seen = new Map();
    for (const item of items || []) this.add(item);
  }

  add(item) {
    const key = canonicalKey(item);
    if (!this.seen.has(key)) {
      this.seen.set(key, this.items.length);
      this.items.push(item);
    }
  }
}

export class PyDict {
  constructor(entries) {
    this.entries = [];
    this.index = new Map();
    for (const [key, value] of entries || []) this.set(key, value);
  }

  set(key, value) {
    const stamp = canonicalKey(key);
    const at = this.index.get(stamp);
    if (at === undefined) {
      this.index.set(stamp, this.entries.length);
      this.entries.push([key, value]);
    } else {
      this.entries[at] = [this.entries[at][0], value];
    }
  }
}

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes;
  }
}

export class PyComplex {
  constructor(real, imag) {
    this.real = real;
    this.imag = imag;
  }
}

export function isNumericValue(value) {
  return typeof value === 'bigint' || typeof value === 'number' || typeof value === 'boolean';
}

export function canonicalKey(value) {
  if (value === null) return 'null';
  if (typeof value === 'boolean') return value ? 'num:1' : 'num:0';
  if (typeof value === 'bigint') return 'num:' + value.toString(10);
  if (typeof value === 'number') {
    if (Number.isNaN(value)) return 'num:nan';
    if (value === Infinity) return 'num:inf';
    if (value === -Infinity) return 'num:-inf';
    if (Object.is(value, -0)) return 'num:-0';
    return 'num:' + String(value);
  }
  if (typeof value === 'string') return 'str:' + value;
  if (value instanceof PyBytes) return 'bytes:' + value.bytes.join(',');
  if (value instanceof PyTuple) return 'tuple:' + value.items.map(canonicalKey).join('|');
  if (value instanceof PyComplex) return 'complex:' + String(value.real) + ':' + String(value.imag);
  return 'obj:' + String(value);
}

export function numericCompare(a, b) {
  const av = typeof a === 'boolean' ? (a ? 1n : 0n) : a;
  const bv = typeof b === 'boolean' ? (b ? 1n : 0n) : b;
  if (typeof av === 'bigint' && typeof bv === 'bigint') {
    return av < bv ? -1 : av > bv ? 1 : 0;
  }
  const an = typeof av === 'bigint' ? bigintToNumber(av) : av;
  const bn = typeof bv === 'bigint' ? bigintToNumber(bv) : bv;
  if (Number.isNaN(an) && Number.isNaN(bn)) return 0;
  if (Number.isNaN(an)) return 1;
  if (Number.isNaN(bn)) return -1;
  return an < bn ? -1 : an > bn ? 1 : 0;
}

function bigintToNumber(value) {
  const max = BigInt(Number.MAX_SAFE_INTEGER);
  const min = -max;
  if (value > max) return Infinity;
  if (value < min) return -Infinity;
  return Number(value);
}

