import { PyBytes, PyComplex, PyDict, PySet, PyTuple } from './python_values.mjs';

export function evaluatePython(source) {
  const parser = new Parser(source);
  const value = parser.parseExpression(0);
  parser.skipSpace();
  if (!parser.atEnd()) parser.fail('unexpected trailing input');
  return value;
}

class Parser {
  constructor(source) {
    this.source = source;
    this.pos = 0;
  }

  atEnd() {
    return this.pos >= this.source.length;
  }

  peek(offset = 0) {
    return this.source[this.pos + offset];
  }

  fail(message) {
    throw new Error(message + ' at offset ' + this.pos);
  }

  skipSpace() {
    while (!this.atEnd()) {
      const ch = this.peek();
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v') {
        this.pos += 1;
      } else if (ch === '#') {
        while (!this.atEnd() && this.peek() !== '\n') this.pos += 1;
      } else {
        break;
      }
    }
  }

  take(text) {
    if (this.source.startsWith(text, this.pos)) {
      this.pos += text.length;
      return true;
    }
    return false;
  }

  expect(text) {
    if (!this.take(text)) this.fail('expected ' + text);
  }

  parseExpression(minPrecedence) {
    let left = this.parseUnary();
    for (;;) {
      this.skipSpace();
      let op = null;
      let precedence = 0;
      let rightAssociative = false;
      if (this.take('**')) {
        op = '**';
        precedence = 60;
        rightAssociative = true;
      } else if (this.take('//')) {
        op = '//';
        precedence = 50;
      } else if (this.peek() === '*' || this.peek() === '/' || this.peek() === '%') {
        op = this.peek();
        this.pos += 1;
        precedence = 50;
      } else if (this.peek() === '+' || this.peek() === '-') {
        op = this.peek();
        this.pos += 1;
        precedence = 40;
      } else {
        break;
      }
      if (precedence < minPrecedence) {
        this.pos -= op.length;
        break;
      }
      const right = this.parseExpression(rightAssociative ? precedence : precedence + 1);
      left = applyBinary(op, left, right);
    }
    return left;
  }

  parseUnary() {
    this.skipSpace();
    if (this.take('+')) return this.parseUnary();
    if (this.take('-')) return negateValue(this.parseUnary());
    return this.parsePrimary();
  }

  parsePrimary() {
    this.skipSpace();
    const ch = this.peek();
    if (ch === undefined) this.fail('unexpected end of input');
    if (this.isStringStart()) {
      let value = this.parseStringLiteral();
      for (;;) {
        this.skipSpace();
        if (!this.isStringStart()) break;
        const next = this.parseStringLiteral();
        if (value instanceof PyBytes && next instanceof PyBytes) {
          value = new PyBytes(value.bytes.concat(next.bytes));
        } else if (typeof value === 'string' && typeof next === 'string') {
          value += next;
        } else {
          this.fail('cannot mix bytes and text');
        }
      }
      return value;
    }
    if (isDigit(ch) || (ch === '.' && isDigit(this.peek(1)))) return this.parseNumber();
    if (ch === '(') return this.parseParenthesized();
    if (ch === '[') return this.parseList();
    if (ch === '{') return this.parseBrace();
    if (isNameStart(ch)) return this.parseName();
    this.fail('unexpected character ' + ch);
  }

  parseName() {
    const start = this.pos;
    this.pos += 1;
    while (!this.atEnd() && isNamePart(this.peek())) this.pos += 1;
    const name = this.source.slice(start, this.pos);
    if (name === 'True') return true;
    if (name === 'False') return false;
    if (name === 'None') return null;
    this.skipSpace();
    if (this.peek() === '(') {
      this.pos += 1;
      const args = [];
      this.skipSpace();
      if (!this.take(')')) {
        for (;;) {
          args.push(this.parseExpression(0));
          this.skipSpace();
          if (this.take(',')) {
            this.skipSpace();
            if (this.take(')')) break;
            continue;
          }
          this.expect(')');
          break;
        }
      }
      return callBuiltin(name, args);
    }
    this.fail('unknown name ' + name);
  }

  parseParenthesized() {
    this.expect('(');
    this.skipSpace();
    if (this.take(')')) return new PyTuple([]);
    const first = this.parseExpression(0);
    this.skipSpace();
    if (!this.take(',')) {
      this.expect(')');
      return first;
    }
    const items = [first];
    this.skipSpace();
    if (this.take(')')) return new PyTuple(items);
    for (;;) {
      items.push(this.parseExpression(0));
      this.skipSpace();
      if (this.take(',')) {
        this.skipSpace();
        if (this.take(')')) break;
        continue;
      }
      this.expect(')');
      break;
    }
    return new PyTuple(items);
  }

  parseList() {
    this.expect('[');
    const items = [];
    this.skipSpace();
    if (this.take(']')) return items;
    for (;;) {
      items.push(this.parseExpression(0));
      this.skipSpace();
      if (this.take(',')) {
        this.skipSpace();
        if (this.take(']')) break;
        continue;
      }
      this.expect(']');
      break;
    }
    return items;
  }

  parseBrace() {
    this.expect('{');
    this.skipSpace();
    if (this.take('}')) return new PyDict([]);
    const first = this.parseExpression(0);
    this.skipSpace();
    if (this.take(':')) {
      const entries = [];
      const firstValue = this.parseExpression(0);
      entries.push([first, firstValue]);
      this.skipSpace();
      if (this.take(',')) {
        this.skipSpace();
        if (!this.take('}')) {
          for (;;) {
            const key = this.parseExpression(0);
            this.skipSpace();
            this.expect(':');
            const value = this.parseExpression(0);
            entries.push([key, value]);
            this.skipSpace();
            if (this.take(',')) {
              this.skipSpace();
              if (this.take('}')) break;
              continue;
            }
            this.expect('}');
            break;
          }
        }
      } else {
        this.expect('}');
      }
      return new PyDict(entries);
    }
    const items = [first];
    this.skipSpace();
    if (this.take(',')) {
      this.skipSpace();
      if (!this.take('}')) {
        for (;;) {
          items.push(this.parseExpression(0));
          this.skipSpace();
          if (this.take(',')) {
            this.skipSpace();
            if (this.take('}')) break;
            continue;
          }
          this.expect('}');
          break;
        }
      }
    } else {
      this.expect('}');
    }
    return new PySet(items);
  }

  isStringStart() {
    let at = this.pos;
    for (let count = 0; count < 2; count += 1) {
      const ch = this.source[at];
      if (ch === '\'' || ch === '"') return true;
      if (ch === 'r' || ch === 'R' || ch === 'b' || ch === 'B' || ch === 'u' || ch === 'U') {
        at += 1;
        continue;
      }
      return false;
    }
    return this.source[at] === '\'' || this.source[at] === '"';
  }

  parseStringLiteral() {
    let raw = false;
    let bytes = false;
    for (;;) {
      const ch = this.peek();
      if (ch === 'r' || ch === 'R') {
        raw = true;
        this.pos += 1;
      } else if (ch === 'b' || ch === 'B') {
        bytes = true;
        this.pos += 1;
      } else if (ch === 'u' || ch === 'U') {
        this.pos += 1;
      } else {
        break;
      }
    }
    const quote = this.peek();
    if (quote !== '\'' && quote !== '"') this.fail('expected string literal');
    this.pos += 1;
    const triple = this.peek() === quote && this.peek(1) === quote;
    if (triple) this.pos += 2;
    const text = [];
    const byteValues = [];
    let closed = false;
    while (!this.atEnd()) {
      if (triple) {
        if (this.peek() === quote && this.peek(1) === quote && this.peek(2) === quote) {
          this.pos += 3;
          closed = true;
          break;
        }
      } else if (this.peek() === quote) {
        this.pos += 1;
        closed = true;
        break;
      }
      if (!triple && this.peek() === '\n') this.fail('unterminated string literal');
      let ch = this.peek();
      this.pos += 1;
      if (ch === '\\' && !raw) {
        const decoded = this.readEscape(bytes);
        if (bytes) {
          for (const b of decoded.bytes) byteValues.push(b);
        } else {
          text.push(decoded.text);
        }
        continue;
      }
      if (ch === '\\' && raw) {
        text.push('\\');
        continue;
      }
      if (bytes) {
        const code = ch.codePointAt(0);
        if (code > 127) this.fail('bytes can only contain ASCII characters');
        byteValues.push(code);
      } else {
        text.push(ch);
      }
    }
    if (!closed) this.fail('unterminated string literal');
    return bytes ? new PyBytes(byteValues) : text.join('');
  }

  readEscape(asBytes) {
    if (this.atEnd()) this.fail('trailing escape');
    let ch = this.peek();
    this.pos += 1;
    const simple = {
      '\\': '\\',
      '\'': '\'',
      '"': '"',
      a: '\x07',
      b: '\x08',
      f: '\x0c',
      n: '\n',
      r: '\r',
      t: '\t',
      v: '\x0b',
      '0': '\x00'
    };
    if (Object.prototype.hasOwnProperty.call(simple, ch) && ch !== '0') {
      return asBytes ? { bytes: [simple[ch].charCodeAt(0)] } : { text: simple[ch] };
    }
    if (ch === '\n') return asBytes ? { bytes: [] } : { text: '' };
    if (ch === 'x') {
      const value = this.readFixedHex(2);
      return asBytes ? { bytes: [value] } : { text: String.fromCodePoint(value) };
    }
    if (!asBytes && ch === 'u') {
      return { text: String.fromCodePoint(this.readFixedHex(4)) };
    }
    if (!asBytes && ch === 'U') {
      return { text: String.fromCodePoint(this.readFixedHex(8)) };
    }
    if (ch >= '0' && ch <= '7') {
      let value = ch.charCodeAt(0) - 48;
      for (let n = 0; n < 2; n += 1) {
        const next = this.peek();
        if (next < '0' || next > '7') break;
        value = value * 8 + (next.charCodeAt(0) - 48);
        this.pos += 1;
      }
      return asBytes ? { bytes: [value & 255] } : { text: String.fromCodePoint(value) };
    }
    const kept = '\\' + ch;
    return asBytes ? { bytes: [92, ch.charCodeAt(0) & 255] } : { text: kept };
  }

  readFixedHex(count) {
    let value = 0;
    for (let n = 0; n < count; n += 1) {
      const ch = this.peek();
      if (ch === undefined) this.fail('short escape');
      const digit = hexValue(ch);
      if (digit < 0) this.fail('bad escape');
      value = value * 16 + digit;
      this.pos += 1;
    }
    return value;
  }

  parseNumber() {
    const start = this.pos;
    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X' || this.peek(1) === 'o' || this.peek(1) === 'O' || this.peek(1) === 'b' || this.peek(1) === 'B')) {
      const marker = this.peek(1).toLowerCase();
      this.pos += 2;
      const digitStart = this.pos;
      while (!this.atEnd()) {
        const ch = this.peek();
        if (ch === '_') {
          this.pos += 1;
          continue;
        }
        const ok = marker === 'x' ? hexValue(ch) >= 0 : marker === 'o' ? (ch >= '0' && ch <= '7') : (ch === '0' || ch === '1');
        if (!ok) break;
        this.pos += 1;
      }
      if (this.pos === digitStart) this.fail('bad integer literal');
      const body = this.source.slice(digitStart, this.pos).split('_').join('');
      return BigInt((marker === 'x' ? '0x' : marker === 'o' ? '0o' : '0b') + body);
    }

    let sawDot = false;
    let sawExponent = false;
    if (this.peek() === '.') {
      sawDot = true;
      this.pos += 1;
      this.consumeDigits();
    } else {
      this.consumeDigits();
      if (this.peek() === '.' && this.peek(1) !== '.') {
        sawDot = true;
        this.pos += 1;
        this.consumeDigits();
      }
    }
    if (this.peek() === 'e' || this.peek() === 'E') {
      const save = this.pos;
      this.pos += 1;
      if (this.peek() === '+' || this.peek() === '-') this.pos += 1;
      if (isDigit(this.peek())) {
        sawExponent = true;
        this.consumeDigits();
      } else {
        this.pos = save;
      }
    }
    let complex = false;
    if (this.peek() === 'j' || this.peek() === 'J') {
      complex = true;
      this.pos += 1;
    }
    const raw = this.source.slice(start, this.pos);
    const clean = raw.split('_').join('');
    if (!sawDot && !sawExponent && !complex) {
      const whole = clean;
      if (whole.length > 1 && whole[0] === '0') this.fail('leading zeros are not allowed');
      return BigInt(whole);
    }
    const number = Number(clean);
    if (complex) return new PyComplex(0, number);
    return number;
  }

  consumeDigits() {
    while (!this.atEnd()) {
      const ch = this.peek();
      if (isDigit(ch) || ch === '_') this.pos += 1;
      else break;
    }
  }
}

function callBuiltin(name, args) {
  if (name === 'float') {
    if (args.length === 0) return 0;
    return toFloat(args[0]);
  }
  if (name === 'int') {
    if (args.length === 0) return 0n;
    const value = args[0];
    if (typeof value === 'bigint') return value;
    if (typeof value === 'boolean') return value ? 1n : 0n;
    if (typeof value === 'number') return BigInt(Math.trunc(value));
    if (typeof value === 'string') return BigInt(value.trim());
    throw new Error('bad int argument');
  }
  if (name === 'complex') {
    const real = args.length > 0 ? toFloat(args[0]) : 0;
    const imag = args.length > 1 ? toFloat(args[1]) : 0;
    return new PyComplex(real, imag);
  }
  if (name === 'set' || name === 'frozenset') return new PySet(iterableItems(args[0]));
  if (name === 'tuple') return new PyTuple(iterableItems(args[0]));
  if (name === 'list') return iterableItems(args[0]);
  if (name === 'dict') {
    if (args[0] instanceof PyDict) return new PyDict(args[0].entries);
    return new PyDict(iterableItems(args[0]));
  }
  if (name === 'bytes' || name === 'bytearray') {
    const value = args[0];
    if (value instanceof PyBytes) return new PyBytes(value.bytes);
    if (typeof value === 'string') {
      const out = [];
      for (const ch of value) {
        const code = ch.codePointAt(0);
        if (code > 255) throw new Error('byte value out of range');
        out.push(code);
      }
      return new PyBytes(out);
    }
    return new PyBytes(iterableItems(value).map((item) => Number(item) & 255));
  }
  throw new Error('unsupported call ' + name);
}

function iterableItems(value) {
  if (value instanceof PyTuple) return value.items;
  if (value instanceof PySet) return value.items;
  if (Array.isArray(value)) return value;
  if (value instanceof PyDict) return value.entries.map(([key]) => key);
  if (typeof value === 'string') return value.split('');
  return [];
}

function toFloat(value) {
  if (typeof value === 'number') return value;
  if (typeof value === 'bigint') return Number(value);
  if (typeof value === 'boolean') return value ? 1 : 0;
  if (typeof value === 'string') {
    const text = value.trim().toLowerCase();
    if (text === 'inf' || text === '+inf' || text === 'infinity' || text === '+infinity') return Infinity;
    if (text === '-inf' || text === '-infinity') return -Infinity;
    if (text === 'nan') return NaN;
    return Number(text);
  }
  throw new Error('bad float argument');
}

function negateValue(value) {
  if (typeof value === 'bigint') return -value;
  if (typeof value === 'number') return -value;
  if (value instanceof PyComplex) return new PyComplex(-value.real, -value.imag);
  throw new Error('bad unary minus');
}

function applyBinary(op, left, right) {
  if (left instanceof PyComplex || right instanceof PyComplex) {
    const a = left instanceof PyComplex ? left : new PyComplex(toFloat(left), 0);
    const b = right instanceof PyComplex ? right : new PyComplex(toFloat(right), 0);
    if (op === '+') return new PyComplex(a.real + b.real, a.imag + b.imag);
    if (op === '-') return new PyComplex(a.real - b.real, a.imag - b.imag);
    throw new Error('unsupported complex operation');
  }
  if (typeof left === 'bigint' && typeof right === 'bigint' && op !== '/') {
    if (op === '+') return left + right;
    if (op === '-') return left - right;
    if (op === '*') return left * right;
    if (op === '//') return floorDivBig(left, right);
    if (op === '%') return modBig(left, right);
    if (op === '**') return powBig(left, right);
  }
  const a = typeof left === 'bigint' ? Number(left) : left;
  const b = typeof right === 'bigint' ? Number(right) : right;
  if (op === '+') return a + b;
  if (op === '-') return a - b;
  if (op === '*') return a * b;
  if (op === '/') return a / b;
  if (op === '//') return Math.floor(a / b);
