import { PyBytes, PyComplex, PyDict, PySet, PyTuple, numericCompare } from './python_values.mjs';

export function dumpYaml(value) {
  const emitted = emitNode(value, 0);
  const lines = emitted.lines;
  if (emitted.plainRootScalar) lines.push('...');
  return lines.join('\n') + '\n';
}

function emitNode(value, indent) {
  if (value === null || typeof value === 'boolean' || typeof value === 'bigint' || typeof value === 'number' || typeof value === 'string' || value instanceof PyComplex) {
    const scalar = scalarLines(value, indent);
    return { lines: scalar.lines, plainRootScalar: indent === 0 && scalar.plain && scalar.lines.length >= 1, flow: true };
  }
  if (value instanceof PyBytes) return bytesLines(value, indent);
  if (value instanceof PyTuple) {
    if (value.items.length === 0) return { lines: [spaces(indent) + '!!python/tuple []'], flow: true };
    return { lines: [spaces(indent) + '!!python/tuple'].concat(sequenceLines(value.items, indent)), flow: false };
  }
  if (value instanceof PySet) {
    if (value.items.length === 0) return { lines: [spaces(indent) + '!!set {}'], flow: true };
    return { lines: [spaces(indent) + '!!set'].concat(setLines(value.items, indent)), flow: false };
  }
  if (Array.isArray(value)) {
    if (value.length === 0) return { lines: ['[]'], flow: true };
    return { lines: sequenceLines(value, indent), flow: false };
  }
  if (value instanceof PyDict) {
    if (value.entries.length === 0) return { lines: ['{}'], flow: true };
    return { lines: mappingLines(value.entries, indent), flow: false };
  }
  return { lines: [spaces(indent) + 'null'], flow: true };
}

function sequenceLines(items, indent) {
  const out = [];
  for (const item of items) {
    if (isInlineValue(item)) {
      const scalar = scalarLines(item, indent);
      out.push(spaces(indent) + '- ' + scalar.lines[0]);
      for (let n = 1; n < scalar.lines.length; n += 1) out.push(scalar.lines[n]);
      continue;
    }
    if (item instanceof PyBytes) {
      const child = bytesLines(item, indent + 2);
      out.push(spaces(indent) + '- ' + child.lines[0].slice(indent + 2));
      for (let n = 1; n < child.lines.length; n += 1) out.push(child.lines[n]);
      continue;
    }
    const child = emitNode(item, indent + 2);
    const first = child.lines[0].slice(indent + 2);
    out.push(spaces(indent) + '- ' + first);
    for (let n = 1; n < child.lines.length; n += 1) out.push(child.lines[n]);
  }
