}

function mappingLines(entries, indent) {
  const out = [];
  for (const [key, value] of sortedEntries(entries)) {
    const keyText = keyScalarText(key);
    const head = spaces(indent) + keyText + ':';
    if (isInlineValue(value)) {
      const scalar = scalarLines(value, indent);
      out.push(head + ' ' + scalar.lines[0]);
      for (let n = 1; n < scalar.lines.length; n += 1) out.push(scalar.lines[n]);
