const HELP = USAGE + '\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n';

export function parseArgs(argv) {
  let value;
  let hasValue = false;
  const extras = [];
  let stopOptions = false;
  for (let at = 0; at < argv.length; at += 1) {
    const arg = argv[at];
    if (!stopOptions && (arg === '-h' || arg === '--help')) {
      return { kind: 'help', text: HELP };
    }
    if (!stopOptions && arg === '--') {
      stopOptions = true;
      continue;
    }
    if (!stopOptions && (arg === '--a' || arg.startsWith('--a='))) {
      if (arg.startsWith('--a=')) {
        value = arg.slice(4);
        hasValue = true;
        continue;
      }
