      if (next === undefined || looksLikeOption(next)) {
        return { kind: 'error', text: USAGE + '\n' + PROG + ': error: argument --a: expected one argument\n', code: 2 };
      }
      value = next;
      hasValue = true;
      at += 1;
      continue;
    }
    extras.push(arg);
  }
  if (!hasValue) {
    return { kind: 'error', text: USAGE + '\n' + PROG + ': error: the following arguments are required: --a\n', code: 2 };
  }
  if (extras.length > 0) {
    return { kind: 'error', text: USAGE + '\n' + PROG + ': error: unrecognized arguments: ' + extras.join(' ') + '\n', code: 2 };
  }
  return { kind: 'ok', value };
}

function looksLikeOption(text) {
  if (text.length <= 1 || text[0] !== '-') return false;
  const second = text[1];
  if (second >= '0' && second <= '9') return false;
  if (second === '.' && text.length > 2 && text[2] >= '0' && text[2] <= '9') return false;
  return true;
}

