import { parseArgs } from './lib/argparse.mjs';
import { evaluatePython } from './lib/python_parser.mjs';
import { dumpYaml } from './lib/yaml_emitter.mjs';

const parsed = parseArgs(process.argv.slice(2));

if (parsed.kind === 'help') {
  process.stdout.write(parsed.text);
} else if (parsed.kind === 'error') {
  process.stderr.write(parsed.text);
  process.exitCode = parsed.code;
} else {
  try {
    const value = evaluatePython(parsed.value);
    process.stdout.write(dumpYaml(value) + '\n');
  } catch (error) {
    process.stderr.write('Traceback (most recent call last):\n');
    process.exitCode = 1;
  }
}

